#include "local_candidate_background_adapter.hpp"
#include "local_candidate_background.hpp"
#include <QCoreApplication>
#include <QFile>
#include <QJsonDocument>
#include <QTextStream>
#include <stdexcept>
static void check(bool ok,const char*why){if(!ok)throw std::runtime_error(why);}
static QJsonObject read(QString p){QFile f(p);check(f.open(QIODevice::ReadOnly),"fixture read");return QJsonDocument::fromJson(f.readAll()).object();}
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{check(argc==4,"fixture/output/v1 paths");auto fixtures=read(argv[1]);QJsonArray outputs;QJsonObject baseline;int good=0,rejected=0;for(auto value:fixtures["cases"].toArray()){auto c=value.toObject(),input=c["input"].toObject();QJsonObject result;bool threw=false;try{result=localCandidateBackgroundAdapter::freeze(input);}catch(const std::exception&){threw=true;}check(threw==c["reject"].toBool(),qPrintable(c["name"].toString()+" rejection mismatch"));if(threw){outputs.append(QJsonObject{{"name",c["name"]},{"rejected",true}});++rejected;continue;}++good;localCandidateBackgroundAdapter::verify(result);check(result["input"]==input,"actual input frozen");auto expected=c["expected"].toObject();for(auto id:expected.keys())for(auto key:expected[id].toObject().keys())check(result["backgrounds"].toObject()[id].toObject()[key].toObject()["status"]==expected[id].toObject()[key],qPrintable(c["name"].toString()+" "+key));for(auto bg:result["backgrounds"].toObject()){auto b=bg.toObject();auto e=localCandidateBackground::evaluate(b,b["holdings"].toObject()["securityId"].toString(),"stable",QDateTime::fromString(input["capturedAt"].toString(),Qt::ISODateWithMs));check(e.contains("knownDelta"),"v38 accepts projection");}
 auto bg=result["backgrounds"].toObject()["SH:stock:600001"].toObject();if(c["name"]=="actual-native-fields"){baseline=result;auto h=bg["holdings"].toObject()["items"].toArray()[0].toObject();check(h["businessAsOf"]=="2026-10-12"&&h["observedAt"]==input["capturedAt"],"observation did not replace business time");check(bg["recent"].toObject()["items"].toArray()[0].toObject()["viewedAt"]=="2026-10-13T07:00:00.000Z","original view time retained");check(bg["leaders"].toObject()["items"].toArray()[0].toObject()["configUpdatedAt"]=="2026-10-12T04:00:00.000Z","configuration date retained");}
 if(c["name"]=="rank81-not-recent"||c["name"]=="native-full-market-no-guess")check(bg["recent"].toObject()["items"].toArray().isEmpty(),"no recent rank/backfill/market inference");if(c["name"]=="ledger-business-time-blank"||c["name"]=="ledger-business-time-null")check(bg["holdings"].toObject()["items"].toArray()[0].toObject()["businessAsOf"].isNull(),"unknown business time not filled");outputs.append(QJsonObject{{"name",c["name"]},{"result",result}});
 }
 auto legacy=read(argv[3]);QJsonObject stock;for(auto v:legacy["cases"].toArray()){auto c=v.toObject();if(c.contains("error"))continue;auto rows=c["result"].toObject()["rows"].toArray();if(!rows.isEmpty()&&rows[0].toObject()["rawScore"].isDouble()){stock=c["selected"].toArray()[0].toObject();break;}}stock["id"]="SH:stock:600001";stock["symbol"]="sh600001";auto cut=QDateTime::fromString(baseline["input"].toObject()["capturedAt"].toString(),Qt::ISODateWithMs);auto v1=localCandidate::evaluate(localCandidate::snapshot(QJsonArray{stock},"stable",cut));stock["backgroundInput"]=baseline["backgrounds"].toObject()["SH:stock:600001"];auto v2=localCandidate::evaluate(localCandidate::snapshot(QJsonArray{stock},"stable",cut));localCandidate::verify(v2);auto a=v1["rows"].toArray()[0].toObject(),b=v2["rows"].toArray()[0].toObject();check(a["factors"]==b["factors"]&&b["rawScore"].toInt()==a["rawScore"].toInt()+30,"existing technical model plus known30 only");check(b["backgroundEvaluation"].toObject()["completeDelta"].isNull(),"unprovided theme/demand remains unknown");auto bad=baseline;bad["inputHash"]="tampered";bool failed=false;try{localCandidateBackgroundAdapter::verify(bad);}catch(...){failed=true;}check(failed,"adapter tamper rejected");failed=false;try{localCandidateBackgroundAdapter::freeze(baseline["input"].toObject(),[]{return true;});}catch(...){failed=true;}check(failed,"adapter cancel");QFile f(argv[2]);check(f.open(QIODevice::WriteOnly),"own parity output");f.write(QJsonDocument(outputs).toJson(QJsonDocument::Compact));QTextStream(stdout)<<"PASS Qt adapter "<<good<<" converted, "<<rejected<<" rejected; frozen hash/roundtrip, v38 model composition, unchanged technical factors\n";return 0;}catch(const std::exception&e){QTextStream(stderr)<<e.what()<<'\n';return 1;}}
